// WriteMessageFlat(message, view) -> bytes written, or -1: null is the None
// terminator; a value outside the generated class set writes NOTHING (a tag
// with no payload would desynchronize the stream). Tag framing is the
// runtime tier's exactly; the message body inlines beneath the tag bits.
export const WriteMessageFlat = PRODUCTION ? writeMessageFlatProduction : writeMessageFlatChecked;

// ReadMessageFlat(storage, message, view, numBits) -> bool: the tag, then
// the message into the caller's MessageStorage (zeroed to the §5 form
// first — the union's own discipline); message.value is null under a None
// tag (the terminator, a success), the storage's instance otherwise.
export function ReadMessageFlat(storage, message, view, numBits) {
  let v = 0, bi = 0, wlo = 0, whi = 0, s2 = 0, out = 0;
  let bg = 0n;
  let br = 0;
  message.value = null;
  if (br + 3 > numBits) {
    return false;
  }
  bi = br >>> 3;
  wlo = view.getUint32(bi, true);
  whi = view.getUint32(bi + 4, true);
  s2 = br & 7;
  out = s2 === 0 ? wlo : ((wlo >>> s2) | (whi << (32 - s2)));
  br += 3;
  v = (out & 0x7) >>> 0;
  if (v > 6) { // a tag outside the set is refused
    return false;
  }
  switch (v) {
    case 0:
      return true; // the None terminator — message stays null
    case 1: { // Block
      const value = storage.Block;
      value.Data.fill(0);
      value.DataLength = 0;
      if (br + 11 > numBits) {
        return false;
      }
      bi = br >>> 3;
      wlo = view.getUint32(bi, true);
      whi = view.getUint32(bi + 4, true);
      s2 = br & 7;
      out = s2 === 0 ? wlo : ((wlo >>> s2) | (whi << (32 - s2)));
      br += 11;
      v = (out & 0x7ff) >>> 0;
      if (v > 2000) { // the length guards the slice — reject, never clamp
        return false;
      }
      value.DataLength = v;
      s2 = br & 7;
      if (s2 !== 0) {
        if (br + (8 - s2) > numBits) {
          return false;
        }
        if ((view.getUint8(br >>> 3) >>> s2) !== 0) { // nonzero padding is refused
          return false;
        }
        br += 8 - s2;
      }
      if (br + value.DataLength * 8 > numBits) {
        return false;
      }
      bi = br >>> 3;
      for (let i0 = 0; i0 < value.DataLength; i0++) {
        value.Data[i0] = view.getUint8(bi + i0);
      }
      br += value.DataLength * 8;
      message.value = value;
      return true;
    }
    case 2: { // Chat
      const value = storage.Chat;
      value.Text.fill(0);
      value.TextLength = 0;
      if (br + 9 > numBits) {
        return false;
      }
      bi = br >>> 3;
      wlo = view.getUint32(bi, true);
      whi = view.getUint32(bi + 4, true);
      s2 = br & 7;
      out = s2 === 0 ? wlo : ((wlo >>> s2) | (whi << (32 - s2)));
      br += 9;
      v = (out & 0x1ff) >>> 0;
      if (v > 256) { // the length guards the slice — reject, never clamp
        return false;
      }
      value.TextLength = v;
      s2 = br & 7;
      if (s2 !== 0) {
        if (br + (8 - s2) > numBits) {
          return false;
        }
        if ((view.getUint8(br >>> 3) >>> s2) !== 0) { // nonzero padding is refused
          return false;
        }
        br += 8 - s2;
      }
      if (br + value.TextLength * 8 > numBits) {
        return false;
      }
      bi = br >>> 3;
      for (let i0 = 0; i0 < value.TextLength; i0++) {
        value.Text[i0] = view.getUint8(bi + i0);
      }
      br += value.TextLength * 8;
      for (let i0 = 0; i0 < value.TextLength; i0++) {
        if (value.Text[i0] === 0) { // an interior null is content the read refuses
          return false;
        }
      }
      message.value = value;
      return true;
    }
    case 3: { // Heartbeat
      const value = storage.Heartbeat;
      message.value = value;
      return true;
    }
    case 4: { // Synchronize
      const value = storage.Synchronize;
      value.SyncFrame = 0n;
      value.SyncSequence = 0;
      if (br + 80 > numBits) {
        return false;
      }
      bi = br >>> 3;
      wlo = view.getUint32(bi, true);
      whi = view.getUint32(bi + 4, true);
      s2 = br & 7;
      out = s2 === 0 ? wlo : ((wlo >>> s2) | (whi << (32 - s2)));
      br += 32;
      v = out >>> 0;
      SC.setUint32(0, v, true);
      bi = br >>> 3;
      wlo = view.getUint32(bi, true);
      whi = view.getUint32(bi + 4, true);
      s2 = br & 7;
      out = s2 === 0 ? wlo : ((wlo >>> s2) | (whi << (32 - s2)));
      br += 32;
      v = out >>> 0;
      SC.setUint32(4, v, true);
      bg = SC.getBigUint64(0, true);
      value.SyncFrame = bg;
      bi = br >>> 3;
      wlo = view.getUint32(bi, true);
      whi = view.getUint32(bi + 4, true);
      s2 = br & 7;
      out = s2 === 0 ? wlo : ((wlo >>> s2) | (whi << (32 - s2)));
      br += 16;
      v = (out & 0xffff) >>> 0;
      value.SyncSequence = v;
      message.value = value;
      return true;
    }
    case 5: { // Test
      const value = storage.Test;
      value.TestA = 0;
      value.TestB = 0;
      value.TestC = 0;
      value.TestD = 0;
      if (br + 46 > numBits) {
        return false;
      }
      bi = br >>> 3;
      wlo = view.getUint32(bi, true);
      whi = view.getUint32(bi + 4, true);
      s2 = br & 7;
      out = s2 === 0 ? wlo : ((wlo >>> s2) | (whi << (32 - s2)));
      br += 16;
      v = (out & 0xffff) >>> 0;
      value.TestA = v;
      bi = br >>> 3;
      wlo = view.getUint32(bi, true);
      whi = view.getUint32(bi + 4, true);
      s2 = br & 7;
      out = s2 === 0 ? wlo : ((wlo >>> s2) | (whi << (32 - s2)));
      br += 10;
      v = (out & 0x3ff) >>> 0;
      if (v > 1000) { // a smuggled offset is refused
        return false;
      }
      value.TestB = v | 0;
      bi = br >>> 3;
      wlo = view.getUint32(bi, true);
      whi = view.getUint32(bi + 4, true);
      s2 = br & 7;
      out = s2 === 0 ? wlo : ((wlo >>> s2) | (whi << (32 - s2)));
      br += 10;
      v = (out & 0x3ff) >>> 0;
      if (v > 1000) { // a smuggled offset is refused
        return false;
      }
      value.TestC = v | 0;
      bi = br >>> 3;
      wlo = view.getUint32(bi, true);
      whi = view.getUint32(bi + 4, true);
      s2 = br & 7;
      out = s2 === 0 ? wlo : ((wlo >>> s2) | (whi << (32 - s2)));
      br += 10;
      v = (out & 0x3ff) >>> 0;
      if (v > 1000) { // a smuggled offset is refused
        return false;
      }
      value.TestD = v | 0;
      message.value = value;
      return true;
    }
    case 6: { // Timescale
      const value = storage.Timescale;
      value.Scale = 0;
      value.FrameA = 0;
      value.FrameB = 0;
      if (br + 128 > numBits) {
        return false;
      }
      bi = br >>> 3;
      wlo = view.getUint32(bi, true);
      whi = view.getUint32(bi + 4, true);
      s2 = br & 7;
      out = s2 === 0 ? wlo : ((wlo >>> s2) | (whi << (32 - s2)));
      br += 32;
      v = out >>> 0;
      SC.setUint32(0, v, true);
      bi = br >>> 3;
      wlo = view.getUint32(bi, true);
      whi = view.getUint32(bi + 4, true);
      s2 = br & 7;
      out = s2 === 0 ? wlo : ((wlo >>> s2) | (whi << (32 - s2)));
      br += 32;
      v = out >>> 0;
      SC.setUint32(4, v, true);
      value.Scale = SC.getFloat64(0, true);
      bi = br >>> 3;
      wlo = view.getUint32(bi, true);
      whi = view.getUint32(bi + 4, true);
      s2 = br & 7;
      out = s2 === 0 ? wlo : ((wlo >>> s2) | (whi << (32 - s2)));
      br += 32;
      v = out >>> 0;
      value.FrameA = v;
      bi = br >>> 3;
      wlo = view.getUint32(bi, true);
      whi = view.getUint32(bi + 4, true);
      s2 = br & 7;
      out = s2 === 0 ? wlo : ((wlo >>> s2) | (whi << (32 - s2)));
      br += 32;
      v = out >>> 0;
      value.FrameB = v;
      message.value = value;
      return true;
    }
    default:
      // unreachable: the tag was bounded above; the default keeps the
      // verdict total
      return false;
  }
}

